#include <algorithm>
#include <deque>
#include <functional>
#include <limits>
#include <optional>
#include <queue>
#include <tuple>
#include <utility>
#include <vector>

using WEdges = std::vector<std::tuple<int, int, long long>>;
static const long long INF = std::numeric_limits<long long>::max();

static std::vector<std::vector<std::pair<int, long long>>> lists(int n, const WEdges& edges)
{
    std::vector<std::vector<std::pair<int, long long>>> adj(n);
    for (auto [u, v, w] : edges) adj[u].push_back({ v, w });
    return adj;
}

static std::vector<long long> run(int n, const WEdges& edges, int source, int target, std::vector<int>& parent)
{
    auto adj = lists(n, edges);
    std::vector<long long> dist(n, INF);
    parent.assign(n, -1);
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    dist[source] = 0;
    pq.push({ 0, source });
    while (!pq.empty())
    {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        if (u == target) break;
        for (auto [v, w] : adj[u])
            if (d + w < dist[v])
            {
                dist[v] = d + w;
                parent[v] = u;
                pq.push({ dist[v], v });
            }
    }
    return dist;
}

std::vector<long long> dijkstra(int n, const WEdges& edges, int source)
{
    std::vector<int> parent;
    std::vector<long long> dist = run(n, edges, source, -1, parent);
    for (auto& d : dist)
        if (d == INF) d = -1;
    return dist;
}

std::pair<long long, std::vector<int>> cheapest(int n, const WEdges& edges, int from, int to)
{
    std::vector<int> parent;
    std::vector<long long> dist = run(n, edges, from, to, parent);
    if (dist[to] == INF) return { -1, {} };
    std::vector<int> path;
    for (int v = to; v != -1; v = parent[v]) path.push_back(v);
    std::reverse(path.begin(), path.end());
    return { dist[to], path };
}

std::optional<std::vector<long long>> bellmanFord(int n, const WEdges& edges, int source)
{
    std::vector<long long> dist(n, INF);
    dist[source] = 0;
    for (int pass = 0; pass < n; ++pass)
    {
        bool changed = false;
        for (auto [u, v, w] : edges)
            if (dist[u] != INF && dist[u] + w < dist[v]) { dist[v] = dist[u] + w; changed = true; }
        if (!changed) return dist;
    }
    return std::nullopt;                     // still changing on the n-th pass
}

std::vector<long long> zeroOneBfs(int n, const WEdges& edges, int source)
{
    auto adj = lists(n, edges);
    std::vector<long long> dist(n, INF);
    std::deque<int> dq;
    dist[source] = 0;
    dq.push_back(source);
    while (!dq.empty())
    {
        int u = dq.front();
        dq.pop_front();
        for (auto [v, w] : adj[u])
            if (dist[u] + w < dist[v])
            {
                dist[v] = dist[u] + w;
                if (w == 0) dq.push_front(v); else dq.push_back(v);
            }
    }
    for (auto& d : dist)
        if (d == INF) d = -1;
    return dist;
}

