#include <random>

static WEdges both(const WEdges& e) { WEdges out = e; for (auto [u, v, w] : e) out.push_back({ v, u, w }); return out; }

TEST("dijkstra") {
    WEdges g = both({ { 0, 1, 4 }, { 0, 2, 1 }, { 2, 1, 2 }, { 1, 3, 1 }, { 2, 3, 5 }, { 3, 4, 3 } });
    CHECK_EQ(dijkstra(6, g, 0), (std::vector<long long>{ 0, 3, 1, 4, 7, -1 }));
    CHECK_EQ(dijkstra(3, { { 0, 1, 0 }, { 1, 2, 0 } }, 0), (std::vector<long long>{ 0, 0, 0 }));
}
TEST("the cheapest path") {
    WEdges g = both({ { 0, 1, 4 }, { 0, 2, 1 }, { 2, 1, 2 }, { 1, 3, 1 }, { 2, 3, 5 }, { 3, 4, 3 } });
    auto [cost, path] = cheapest(6, g, 0, 4);
    CHECK_EQ(cost, 7LL);
    CHECK_EQ(path, (std::vector<int>{ 0, 2, 1, 3, 4 }));
    CHECK_EQ(cheapest(6, g, 0, 5).first, -1LL);
    CHECK_EQ(cheapest(6, g, 3, 3).second, (std::vector<int>{ 3 }));
}
TEST("100,000 vertices and 300,000 edges") {
    const int n = 100000;
    WEdges e;
    std::mt19937 rng(17);
    for (int i = 0; i + 1 < n; ++i) e.push_back({ i, i + 1, 1000 });
    for (int k = 0; k < 200000; ++k)
    {
        int u = static_cast<int>(rng() % n), v = static_cast<int>(rng() % n);
        e.push_back({ u, v, 1000 + static_cast<long long>(rng() % 100000) });
    }
    auto d = dijkstra(n, e, 0);
    CHECK_EQ(d[0], 0LL);
    CHECK(d[n - 1] > 0 && d[n - 1] <= 1000LL * (n - 1));
    bool tight = true;                                       // every edge satisfies d[v] <= d[u] + w
    for (auto [u, v, w] : e) tight = tight && d[v] <= d[u] + w;
    CHECK(tight);
}
TEST("negative weights") {
    auto d = bellmanFord(3, { { 0, 1, 2 }, { 0, 2, 5 }, { 2, 1, -4 } }, 0);
    CHECK(d.has_value());
    if (d) CHECK_EQ((*d)[1], 1LL);
    CHECK(!bellmanFord(3, { { 0, 1, 1 }, { 1, 2, -2 }, { 2, 1, 1 } }, 0).has_value());
    auto unreachableCycle = bellmanFord(4, { { 0, 1, 3 }, { 2, 3, -5 }, { 3, 2, 1 } }, 0);
    CHECK(unreachableCycle.has_value());
    if (unreachableCycle)
    {
        CHECK_EQ((*unreachableCycle)[1], 3LL);
        CHECK_EQ((*unreachableCycle)[2], std::numeric_limits<long long>::max());
    }
}
TEST("zero-one BFS") {
    CHECK_EQ(zeroOneBfs(5, { { 0, 1, 1 }, { 0, 2, 0 }, { 2, 1, 0 }, { 1, 3, 1 }, { 2, 3, 1 } }, 0), (std::vector<long long>{ 0, 0, 0, 1, -1 }));
    const int n = 200000;
    WEdges e;
    for (int i = 0; i + 1 < n; ++i) { e.push_back({ i, i + 1, i % 2 }); }
    auto d = zeroOneBfs(n, e, 0);
    CHECK_EQ(d[n - 1], static_cast<long long>((n - 1) / 2));
}

